pub const NAMES: [&str; 10] = [
    "trellis_workspace_describe",
    "trellis_find_symbols",
    "trellis_search_symbols",
    "trellis_declaration",
    "trellis_outgoing_calls",
    "trellis_incoming_calls",
    "trellis_read_source",
    "trellis_references",
    "trellis_rules_check",
    "trellis_rules_explain",
];
pub fn known(name: &str) -> bool {
    NAMES.contains(&name)
}
pub fn entries() -> Vec<Value> {
    let mut entries: Vec<Value> = serde_json::from_str(CATALOG).expect("static catalog must parse");
    entries.extend(super::architecture::entries());
    entries
}
pub fn discover(version: &str) -> Value {
    json!({"resultType":"complete","ttlMs":0,"cacheScope":"private",
        "supportedVersions":["2026-07-28","2025-11-25"],"capabilities":{"tools":{},"prompts":{}},
        "_meta":{"io.modelcontextprotocol/serverInfo":{"name":"trellis","version":version}}})
}
pub fn initialize(version: &str) -> Value {
    json!({"protocolVersion":"2025-11-25","capabilities":{"tools":{},"prompts":{}},
        "serverInfo":{"name":"trellis","version":version}})
}
pub fn list(modern: bool) -> Value {
    if modern {
        json!({"resultType":"complete","ttlMs":0,"cacheScope":"private","tools":entries()})
    } else {
        json!({"tools":entries()})
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    use crate::mcp::wire::{CATALOG_BYTES, RESPONSE_BYTES, write_relayed_capped, write_response};
    #[test]
    fn exact_full_catalog_and_bounds() {
        let golden: Value =
            serde_json::from_str(include_str!("../../tests/fixtures/mcp/catalog.json")).unwrap();
        assert_eq!(entries(), golden.as_array().unwrap().to_vec());
        assert_eq!(
            NAMES.map(str::to_owned).to_vec(),
            entries()
                .iter()
                .map(|e| e["name"].as_str().unwrap().to_owned())
                .collect::<Vec<_>>()
        );
        for modern in [false, true] {
            let result = list(modern);
            assert_eq!(result["tools"], golden);
            assert_eq!(result.get("resultType").is_some(), modern);
            for id in [
                json!("\u{0000}".repeat(42) + "aa"),
                json!(9007199254740991_i64),
                json!(-9007199254740991_i64),
            ] {
                let mut wire = Vec::new();
                write_relayed_capped(
                    &mut wire,
                    None,
                    &json!({"jsonrpc":"2.0","id":id,"result":result}),
                    CATALOG_BYTES,
                )
                .unwrap();
                assert!(wire.len() <= CATALOG_BYTES);
                assert_eq!(wire.last(), Some(&b'\n'));
            }
        }
        assert_eq!(
            discover("0.1.0"),
            json!({"resultType":"complete","ttlMs":0,"cacheScope":"private","supportedVersions":["2026-07-28","2025-11-25"],"capabilities":{"tools":{},"prompts":{}},"_meta":{"io.modelcontextprotocol/serverInfo":{"name":"trellis","version":"0.1.0"}}})
        );
        assert_eq!(
            initialize("0.1.0"),
            json!({"protocolVersion":"2025-11-25","capabilities":{"tools":{},"prompts":{}},"serverInfo":{"name":"trellis","version":"0.1.0"}})
        );
        for value in [discover("0.1.0"), initialize("0.1.0")] {
            for id in [
                json!("\u{0000}".repeat(42) + "aa"),
                json!(9007199254740991_i64),
                json!(-9007199254740991_i64),
            ] {
                let mut wire = Vec::new();
                write_response(&mut wire, &json!({"jsonrpc":"2.0","id":id,"result":value}))
                    .unwrap();
                assert!(wire.len() <= RESPONSE_BYTES);
            }
        }
    }
    /// `tools/list` must fit its own catalog cap with room to spare (#165): a
    /// new tool or schema change that eats the headroom fails here, not on the wire.
    #[test]
    fn catalog_frame_keeps_named_headroom() {
        const HEADROOM: usize = 16_384;
        // The largest admitted string ID is 256 bytes as a JSON token.
        let id = json!("\u{0000}".repeat(42) + "aa");
        for modern in [false, true] {
            let mut wire = Vec::new();
            write_relayed_capped(
                &mut wire,
                None,
                &json!({"jsonrpc":"2.0","id":id,"result":list(modern)}),
                CATALOG_BYTES,
            )
            .unwrap();
            assert!(
                wire.len() <= CATALOG_BYTES - HEADROOM,
                "tools/list frame is {} bytes; the catalog budget is {} (catalog cap {} minus {HEADROOM} headroom)",
                wire.len(),
                CATALOG_BYTES - HEADROOM,
                CATALOG_BYTES
            );
        }
    }
    #[test]
    fn every_reference_closed_and_enums_present() {
        fn walk(v: &Value, defs: &serde_json::Map<String, Value>) {
            if let Some(reference) = v.get("$ref").and_then(Value::as_str) {
                assert!(reference.starts_with("#/$defs/"));
                assert!(defs.contains_key(&reference[8..]));
            }
            // A root union of closed branches is itself closed: MCP requires its
            // root `type: "object"` (#158), and each `oneOf` branch is walked below.
            if v.get("type").and_then(Value::as_str) == Some("object") && v.get("oneOf").is_none() {
                assert_eq!(v["additionalProperties"], false);
                let properties = v["properties"].as_object().unwrap();
                let required = v["required"].as_array().unwrap();
                for field in required {
                    assert!(properties.contains_key(field.as_str().unwrap()));
                }
            }
            match v {
                Value::Array(a) => {
                    for x in a {
                        walk(x, defs)
                    }
                }
                Value::Object(o) => {
                    for (k, x) in o {
                        if k != "$defs" {
                            walk(x, defs)
                        }
                    }
                }
                _ => (),
            }
        }
        for e in entries().into_iter().take(7) {
            for side in ["inputSchema", "outputSchema"] {
                let s = &e[side];
                let defs = s["$defs"].as_object().unwrap();
                walk(s, defs);
                for definition in defs.values() {
                    walk(definition, defs);
                }
            }
            let d = &e["outputSchema"]["$defs"];
            assert_eq!(
                d["FailureCode"]["enum"],
                json!([
                    "invalid_request",
                    "range_too_large",
                    "unsupported_encoding",
                    "revision_conflict",
                    "index_not_ready",
                    "not_found",
                    "too_many_requests",
                    "deadline_exceeded",
                    "rebuild_in_progress",
                    "root_changed",
                    "store_unavailable",
                    "workspace_selection_failed",
                    "checkout_capacity",
                    "daemon_unavailable",
                    "outcome_unknown"
                ])
            );
            assert_eq!(
                d["Failure"]["properties"]["error"]["properties"]["code"],
                json!({"$ref":"#/$defs/ResolvedFailureCode"})
            );
            assert!(
                !d["ResolvedFailureCode"]["enum"]
                    .as_array()
                    .unwrap()
                    .contains(&json!("workspace_selection_failed"))
            );
            for name in ["SelectionFailure", "InvalidWorkspaceFailure"] {
                let error = &d[name]["properties"]["error"]["properties"];
                assert_eq!(error["currentBasis"], json!({"const":null}));
                assert_eq!(error["currentContentHash"], json!({"const":null}));
            }
            assert_eq!(
                d["InvalidWorkspaceFailure"]["properties"]["error"]["properties"]["retryable"],
                json!({"const":false})
            );
            assert_eq!(
                e["outputSchema"]["oneOf"]
                    .as_array()
                    .unwrap()
                    .last()
                    .unwrap(),
                &json!({"$ref":"#/$defs/ArgumentFailure"})
            );
            let arguments = &d["ArgumentFailure"];
            assert_eq!(
                arguments["required"],
                json!(["schemaVersion", "requestId", "error"])
            );
            assert_eq!(arguments["additionalProperties"], false);
            assert_eq!(
                arguments["properties"]["error"]["properties"]["code"]["enum"],
                json!(["invalid_request", "range_too_large"])
            );
            assert_eq!(
                d["Warning"]["properties"]["code"]["enum"],
                json!([
                    "coverageIncomplete",
                    "staleEvidence",
                    "staleTarget",
                    "bindingAmbiguous",
                    "syntaxOnly"
                ])
            );
            if e["name"] == "trellis_find_symbols"
                || e["name"] == "trellis_declaration"
                || e["name"] == "trellis_outgoing_calls"
                || e["name"] == "trellis_incoming_calls"
            {
                assert!(
                    d["Provenance"]["required"]
                        .as_array()
                        .unwrap()
                        .contains(&json!("derivedFrom"))
                );
            }
        }
    }
    #[test]
    fn search_is_the_third_closed_tool_with_shared_symbol_fields() {
        let entries = entries();
        let search = &entries[2];
        assert_eq!(search["name"], "trellis_search_symbols");
        assert_eq!(search["inputSchema"]["additionalProperties"], false);
        assert_eq!(search["inputSchema"]["properties"]["limit"]["default"], 10);
        let defs = &search["outputSchema"]["$defs"];
        let mut symbol = entries[1]["outputSchema"]["$defs"]["Symbol"].clone();
        symbol["properties"]["rank"] = defs["SearchHit"]["properties"]["rank"].clone();
        symbol["properties"]["matchedBy"] = defs["SearchHit"]["properties"]["matchedBy"].clone();
        symbol["required"]
            .as_array_mut()
            .unwrap()
            .extend([json!("rank"), json!("matchedBy")]);
        assert_eq!(defs["SearchHit"], symbol);
        assert_eq!(defs["SearchIndexStatus"]["additionalProperties"], false);
        assert_eq!(
            defs["SearchIndexStatus"]["properties"]["backend"]["enum"],
            json!(["cpu", "metal", null])
        );
        assert_eq!(
            entries[0]["outputSchema"]["oneOf"][0]["properties"]["data"]["properties"]["toolVersion"]
                ["const"],
            2
        );
    }

    #[test]
    fn advertised_path_and_basis_patterns_match_contract_cases() {
        // Exercise the catalog's published ECMAScript patterns, not a second Rust
        // approximation or only an equality check against a copied golden.
        let catalog = entries();
        let read = catalog
            .iter()
            .find(|e| e["name"] == "trellis_read_source")
            .unwrap();
        assert_eq!(
            read["inputSchema"]["properties"]["path"],
            json!({"$ref":"#/$defs/ReadSourcePath"})
        );
        assert_eq!(
            read["outputSchema"]["oneOf"][0]["properties"]["data"]["properties"]["path"],
            json!({"$ref":"#/$defs/Path"})
        );
        let mut inputs = Vec::new();
        let paths = json!([
            "src/a:b.rs", // #22 native paths permit colon; read_source input does not.
            "src/a.rs",
            "src/",
            "src//a",
            "./a",
            "src/../a",
            "/a",
            "src/a\\b",
            "src/a\u{0000}b",
            "src\n/../a",
            "src\n/./a",
            "a\r/../b",
            "a\u{2028}/../b",
            "src/a\n/b.rs",
            "src/é\u{2028}/😀.rs",
            "src/.\n",
            "src/..\r",
            "src/a.rs/\n/../b", // Forbidden segment need not follow the first terminator.
            "src/a.rs\n"        // Newline in an ordinary filename is permitted.
        ]);
        let native_expected = json!([
            true, true, false, false, false, false, false, false, false, false, false, false,
            false, true, true, true, true, false, true
        ]);
        let read_expected = json!([
            false, true, false, false, false, false, false, false, false, false, false, false,
            false, true, true, true, true, false, true
        ]);
        for tool in catalog.iter().take(7) {
            for side in ["inputSchema", "outputSchema"] {
                let defs = &tool[side]["$defs"];
                for (definition, expected) in [
                    ("Path", &native_expected),
                    ("ReadSourcePath", &read_expected),
                ] {
                    if let Some(pattern) = defs[definition]["pattern"].as_str() {
                        inputs.push(json!({"pattern":pattern,"values":paths,"expected":expected,
                            "where":format!("{} {side} {definition}",tool["name"])}));
                    }
                }
                if let Some(pattern) =
                    defs["Basis"]["properties"]["indexGeneration"]["pattern"].as_str()
                {
                    inputs.push(json!({"pattern":pattern,"values":[
                        "00000000-0000-0000-0000-000000000000",
                        "123e4567-e89b-42d3-a456-426614174000",
                        "123E4567-e89b-42d3-a456-426614174000",
                        "123e4567-e89b-42d3-a456-42661417400g",
                        "123e4567-e89b-42d3-a456-426614174000\n"],
                        "expected":[false,true,false,false,false],
                        "where":format!("{} {side} Basis",tool["name"])}));
                }
            }
        }
        assert_eq!(inputs.len(), 20); // Six native output Paths, one stricter input Path, thirteen Basis definitions.
        let script = r#"const rows=JSON.parse(process.argv[1]);
          process.stdout.write(JSON.stringify(rows.map(row=>row.values.map(value=>new RegExp(row.pattern).test(value)))));"#;
        let output = std::process::Command::new("node")
            .args(["-e", script, &serde_json::to_string(&inputs).unwrap()])
            .output()
            .expect("Node is required by tools/verify");
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let actual: Value = serde_json::from_slice(&output.stdout).unwrap();
        for (row, result) in inputs.iter().zip(actual.as_array().unwrap()) {
            assert_eq!(&row["expected"], result, "{}", row["where"]);
        }
    }
}
